  const tdCirc = circ(['A', 'B'], [['n', 'NOT', 'A'], ['x', 'XOR', 'A', 'B']], [['F1', 'n'], ['F2', 'x']]);
  const ttTD = tt(['A', 'B'], [['F1 (AB < 2)', "A'B' + A'B"], ['F2 (A ≠ B)', "A'B + AB'"]], { showIndex: true });

  // ALU used throughout (app's own op-code table): F1F0 = 00 AND, 01 OR, 10 ADD, 11 SUB.
  const ALU_OPS = { '00': 'AND', '01': 'OR', '10': 'ADD', '11': 'SUB' };
  function alu(op, a, b) {
    if (op === '00') return { r: andBits(a, b) };
    if (op === '01') return { r: orBits(a, b) };
    const m = op === '11' ? 1 : 0, y = m ? flip(b) : b, s = add(a, y, m);
    return { r: s.s, c: s.cout, v: s.v, y, carries: s.c };
  }
  const aluTable = table(['F1 F0', 'operation', 'R'], [['0 0', 'AND', 'A · B (bitwise)'], ['0 1', 'OR', 'A + B (bitwise OR)'], ['1 0', 'ADD', 'A plus B'], ['1 1', 'SUB', "A minus B = A + B' + 1"]]);

